import sys, traceback
import torch, torch.nn as nn
sys.path.insert(0, "/workspace/SuperGrok1.5")
import grokking_race_v2 as R
from grokking_optimizers import SuperGrok11, SuperGrok15, SuperGrok2

dev = "cuda"
c = dict(R.DEFAULT_CONFIG)
c["model_type"] = "decoder"
# build data the way the race does (small real grokking task)
import torch.nn.functional as F
crit = nn.CrossEntropyLoss()

def real_model():
    return R.build_model(c, dev, False)

def make_data():
    p = c["p"]
    # modular task batch
    n = 256
    a = torch.randint(0, p, (n,), device=dev)
    b = torch.randint(1, p, (n,), device=dev)
    x = torch.stack([a, b], dim=1)  # (n,2) token ids
    y = (a * pow_inv(b, p)) % p if False else (a + b) % p
    return x, y

def pow_inv(b, p):
    return b  # unused

def sharp_nonzero(opt):
    if hasattr(opt, "_flat_sharpness") and opt._flat_sharpness is not None:
        s = opt._flat_sharpness
        try:
            return float(s.abs().sum().item())
        except Exception:
            return float(sum(t.abs().sum().item() for t in s)) if isinstance(s, (list, tuple)) else -1.0
    return None

def run(name, factory, calls, sg2=False):
    print(f"\n===== {name} (real decoder model) =====")
    try:
        m = real_model()
    except Exception as e:
        print(f"  model build failed: {e}"); return
    opt = factory(m)
    if hasattr(opt, "meta_net"): opt.meta_net = opt.meta_net.to(dev)
    mopt = torch.optim.Adam(opt.meta_net.parameters(), lr=1e-4) if hasattr(opt, "meta_net") else None
    tx, ty = make_data(); vax, vay = make_data()
    logits = m(tx); loss = crit(logits[:, :c["p"]] if logits.size(-1) >= c["p"] else logits, ty)
    opt.zero_grad(); loss.backward()
    if sg2:
        print(f"  meta_net.has_cuda_bilevel = {getattr(opt.meta_net, 'has_cuda_bilevel', 'MISSING')}")
    for label, fn in calls(m, opt, mopt, tx, ty, vax, vay):
        before = sharp_nonzero(opt)
        try:
            ret = fn()
            after = sharp_nonzero(opt)
            extra = ""
            if label == "sam_step":
                extra = f" | _flat_sharpness sum: {before} -> {after}"
            print(f"  [OK]    {label}: ran{extra}")
        except Exception as e:
            print(f"  [THROW] {label}: {type(e).__name__}: {e}")
            traceback.print_exc()

def sg11_calls(m, opt, mopt, tx, ty, vax, vay):
    return [("meta_step", lambda: opt.meta_step(m, vax, vay, crit, mopt, tx, ty)),
            ("sam_step",  lambda: opt.sam_step(m, tx, ty, crit))]
def sg_calls(m, opt, mopt, tx, ty, vax, vay):
    return [("sam_step",     lambda: opt.sam_step(m, tx, ty, crit)),
            ("bilevel_step", lambda: opt.bilevel_step(m, tx, ty, vax, vay, crit, mopt))]

run("SuperGrok11", lambda m: SuperGrok11(m.parameters(), lr=1e-3, weight_decay=1.0), sg11_calls)
run("SuperGrok15", lambda m: SuperGrok15(m.parameters(), lr=1e-3, weight_decay=1.0), sg_calls)
run("SuperGrok2", lambda m: SuperGrok2(m.parameters(), lr=1e-3, weight_decay=1.0, d_model=8), sg_calls, sg2=True)
print("\nDONE")

